// Builds the agent input from persistent memory (client1-state SQLite) + notes.md. No LLM here.
const t = $('When called').first().json;
const c = $json || {};
const hist = Array.isArray(c.history) ? c.history : [];
const lines = hist.map(h => (h.role === 'user' ? 'the owner' : 'You') + ': ' + String(h.text).slice(0, 1500));
const editing = String(t.context || '').startsWith('editing:')
  ? 'He reacted ✏️ (edit) on your latest post preview in this thread. This message is the change he wants: rewrite the post and call propose_post again with the full revised text and the same services.'
  : '';
const prompt = (lines.length ? 'Earlier in this Slack thread (oldest first):\n' + lines.join('\n') + '\n\n' : '')
  + (editing ? editing + '\n\n' : '') + 'New Slack message from <@' + t.user + '>:\n' + t.text;
return [{ json: { prompt, notes: String(c.notes || '(notes file unavailable this turn)').slice(0, 8000),
                  guard: String(c.guard || '(limits unavailable this turn: assume caps X 5/3, LinkedIn 3/2, Facebook 5/3 engagement/posts per day)'),
                  thread_key: (t.channel || 'C0000000001') + ':' + (t.thread_ts || t.ts), history_turns: Math.floor(hist.length / 2) } }];

const t = $('When called').first().json;
let out = ($json.output ?? $json.text ?? '').toString().trim();
const err = $json.error ? String($json.error.message || $json.error) : '';
// out-of-scope marker from the agent -> logged by the helper (upsell-log.md + note to the owner), never shown in Slack
let scope = null;
const sm = out.match(/\[\[\s*out[_ ]of[_ ]scope\s*:\s*([^\]]{0,200})\]\]/i);
if (sm) { scope = sm[1].trim(); out = out.replace(sm[0], '').trim(); }
const slackify = x => x.replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s+(.*)$/gm, '*$1*').replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<$2|$1>');
const text = slackify(out) || (err ? `Sorry, I hit an error: ${err.slice(0, 300)}` : 'Sorry, I could not produce a reply.');
const thread = t.thread_ts || t.ts;
const dry = t.dry_run === true || t.dry_run === 'true';
return [{ json: { failed: !out, channel: t.channel || 'C0000000001', thread_ts: thread, text: text.slice(0, 3900),
  dry_run: dry,
  scope: scope ? { op: 'scope', by: t.user, ts: t.ts, thread_ts: thread, channel: t.channel || 'C0000000001', text: String(t.text || '').slice(0, 500), summary: scope, dry_run: dry } : null,
  slack: { channel: t.channel || 'C0000000001', thread_ts: thread, text: text.slice(0, 3900), unfurl_links: false, unfurl_media: false },
  mem: { thread: (t.channel || 'C0000000001') + ':' + thread, user_text: String(t.text || ''), bot_text: text.slice(0, 3900) } } }];

// Slack answer -> read receipt on the human's message (👀 -> ✅, or ⚠️ + note). Announcements/dry runs have none.
const t = $('When called').first().json;
let failed = false; try { failed = !!$('Prepare reply').first().json.failed; } catch (e) {}
const posted = !!$json.ok;
if (t.announce || !t.ts) return [{ json: { ok: posted, posted, ts: $json.ts, receipt: null } }];
return [{ json: { ok: posted, posted, ts: $json.ts, receipt: { channel: t.channel || 'C0000000001', ts: t.ts, ok: posted && !failed,
  note: posted ? '' : 'Sorry, my reply failed to post (' + ($json.error || 'Slack error') + '). Please try again.', thread_ts: t.thread_ts || t.ts } } }];
